sql.smartlist.add:
insert into flow.smartlist (name, company_object_type_id, shared, owner_id, created_by_id, view_object_type_id, main_process_steps, project_details)
values (:name, :companyObjectTypeId, :shared, :ownerId, :createdById, :viewObjectTypeId, true, :projectDetails)
returning id;

sql.smartlist.addField:
insert into flow.smartlist_field_assignment (smartlist_id, smartlist_field_id, custom_field_group_assignment_id, created_by_id, display_order, process_step_id, project_details_column)
values (:smartlistId, :smartlistFieldId, :customFieldGroupAssignmentId, :createdById, :displayOrder, :processStepId, :projectDetailsColumn)
returning id;

sql.smartlist.addRequirement:
insert into flow.smartlist_requirement (smartlist_id, process_step_id, custom_field_group_assignment_id, operator_type_id, requirement_value, secondary_requirement_value, data_type_requirement_id, display_order, created_by_id, smartlist_field_id, list_of_value_id, list_of_value_ids, system_list_option_id, custom_sql_option_id, project_details_column)
values (:smartlistId, :processStepId, :customFieldGroupAssignmentId, :operatorTypeId, :requirementValue, :secondaryRequirementValue, :dataTypeRequirementId, :displayOrder, :userId, :smartlistFieldId, :listOfValueId, array[ :listOfValueIds ]::integer[], :systemListOptionId, :customSqlOptionId, :projectDetailsColumn)
returning id;
